<?php /* BISM4RCK-KUN3H0 2026 */ include app_path('views/layouts/header.php'); ?><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><h2>Admin / Guard Logs</h2><div class="text-muted">Account activity is separate from gate access logs.</div></div><div class="gh-card p-4 mb-3"><form class="row g-2" method="get"><div class="col-md-3"><select class="form-select" name="account_type"><option value="">All account types</option><option value="guard" <?=$activityFilters['account_type']==='guard'?'selected':''?>>Guard</option><option value="admin" <?=$activityFilters['account_type']==='admin'?'selected':''?>>Admin</option></select></div><div class="col-md-4"><select class="form-select" name="user_id"><option value="">All accounts</option><?php foreach($activityUsers as $u): ?><option value="<?=e($u['id'])?>" <?=$activityFilters['user_id']==(string)$u['id']?'selected':''?>><?=e(strtoupper($u['role']).' — '.$u['full_name'].' — '.$u['email'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input class="form-control" name="action" value="<?=e($activityFilters['action'])?>" placeholder="Action, e.g. login"></div><div class="col-md-2"><button class="btn gh-primary w-100">Filter</button></div></form></div><div class="gh-card p-4"><div class="table-responsive"><table class="table gh-table"><thead><tr><th>Time</th><th>Type</th><th>Account</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($activityLogs as $log): ?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['account_type'])?></td><td><?=e($log['user_name']?:$log['account_identifier'])?></td><td><?=e($log['action'])?></td><td><?=e($log['details'])?></td><td><?=e($log['ip_address'])?></td></tr><?php endforeach;?><?php if(empty($activityLogs)): ?><tr><td colspan="6" class="text-center text-muted py-4">No account activity matches.</td></tr><?php endif;?></tbody></table></div></div></div><?php include app_path('views/layouts/footer.php');